package goals

import (
	"encoding/json"
	"net/http"
	"strings"
	"time"

	"github.com/digocelos/financisto/internal/auth"
	"github.com/digocelos/financisto/internal/httpapi"
	"github.com/google/uuid"
	"github.com/jackc/pgx/v5/pgxpool"
)

type Handler struct { db *pgxpool.Pool; auth *auth.Service }
func NewHandler(db *pgxpool.Pool, authService *auth.Service) *Handler { return &Handler{db: db, auth: authService} }
func (h *Handler) MountRoutes(mux *http.ServeMux) { p:=func(fn http.HandlerFunc) http.Handler{return h.auth.RequireUser(fn)}; mux.Handle("GET /v1/families/{familyID}/investment-accounts",p(h.listInvestments)); mux.Handle("POST /v1/families/{familyID}/investment-accounts",p(h.createInvestment)); mux.Handle("POST /v1/families/{familyID}/investment-accounts/{accountID}/movements",p(h.createInvestmentMovement)); mux.Handle("GET /v1/families/{familyID}/vaults",p(h.listVaults)); mux.Handle("POST /v1/families/{familyID}/vaults",p(h.createVault)) }
func (h *Handler) familyID(r *http.Request)(uuid.UUID,bool){ u,ok:=auth.UserIDFromContext(r.Context());if !ok{return uuid.Nil,false};f,e:=uuid.Parse(r.PathValue("familyID"));if e!=nil{return uuid.Nil,false};var allowed bool;e=h.db.QueryRow(r.Context(),`SELECT EXISTS(SELECT 1 FROM family_members WHERE family_id=$1 AND user_id=$2 AND archived_at IS NULL)`,f,u).Scan(&allowed);return f,e==nil&&allowed }
type investmentInput struct{MemberID uuid.UUID `json:"memberId"`;Name string `json:"name"`}
func(h *Handler) createInvestment(w http.ResponseWriter,r *http.Request){f,ok:=h.familyID(r);if !ok{httpapi.WriteProblem(w,404,"family not found");return};var in investmentInput;if json.NewDecoder(r.Body).Decode(&in)!=nil||in.MemberID==uuid.Nil||strings.TrimSpace(in.Name)==""{httpapi.WriteProblem(w,400,"member and name are required");return};var member bool;if err:=h.db.QueryRow(r.Context(),`SELECT EXISTS(SELECT 1 FROM family_members WHERE id=$1 AND family_id=$2 AND archived_at IS NULL)`,in.MemberID,f).Scan(&member);err!=nil||!member{httpapi.WriteProblem(w,400,"member is not part of this family");return};id:=uuid.New();if _,err:=h.db.Exec(r.Context(),`INSERT INTO investment_accounts(id,family_id,member_id,name) VALUES($1,$2,$3,$4)`,id,f,in.MemberID,strings.TrimSpace(in.Name));err!=nil{httpapi.WriteProblem(w,409,"could not create investment account");return};httpapi.WriteJSON(w,201,map[string]any{"id":id,"memberId":in.MemberID,"name":strings.TrimSpace(in.Name),"balanceCents":int64(0)})}
func(h *Handler) listInvestments(w http.ResponseWriter,r *http.Request){f,ok:=h.familyID(r);if !ok{httpapi.WriteProblem(w,404,"family not found");return};rows,err:=h.db.Query(r.Context(),`SELECT a.id,a.member_id,a.name,COALESCE(SUM(CASE WHEN m.kind='WITHDRAWAL' THEN -m.amount_cents ELSE m.amount_cents END),0) FROM investment_accounts a LEFT JOIN investment_movements m ON m.investment_account_id=a.id WHERE a.family_id=$1 AND a.status='ACTIVE' GROUP BY a.id ORDER BY a.created_at`,f);if err!=nil{httpapi.WriteProblem(w,500,"could not load investment accounts");return};defer rows.Close();out:=make([]map[string]any,0);for rows.Next(){var id,member uuid.UUID;var name string;var balance int64;if err:=rows.Scan(&id,&member,&name,&balance);err!=nil{httpapi.WriteProblem(w,500,"could not load investment accounts");return};out=append(out,map[string]any{"id":id,"memberId":member,"name":name,"balanceCents":balance})};httpapi.WriteJSON(w,200,out)}
type movementInput struct{Kind string `json:"kind"`;AmountCents int64 `json:"amountCents"`;EffectiveAt string `json:"effectiveAt"`;Description string `json:"description"`}
func(h *Handler) createInvestmentMovement(w http.ResponseWriter,r *http.Request){f,ok:=h.familyID(r);if !ok{httpapi.WriteProblem(w,404,"family not found");return};id,err:=uuid.Parse(r.PathValue("accountID"));if err!=nil{httpapi.WriteProblem(w,404,"investment account not found");return};var in movementInput;if json.NewDecoder(r.Body).Decode(&in)!=nil||in.AmountCents<=0||in.Description==""{httpapi.WriteProblem(w,400,"kind, amount, date and description are required");return};date,err:=time.Parse("2006-01-02",in.EffectiveAt);if err!=nil{httpapi.WriteProblem(w,400,"effectiveAt must use YYYY-MM-DD");return};if in.Kind!="CONTRIBUTION"&&in.Kind!="WITHDRAWAL"&&in.Kind!="DIVIDEND"&&in.Kind!="INTEREST"&&in.Kind!="ADJUSTMENT"{httpapi.WriteProblem(w,400,"unsupported movement kind");return};var exists bool;if err=h.db.QueryRow(r.Context(),`SELECT EXISTS(SELECT 1 FROM investment_accounts WHERE id=$1 AND family_id=$2 AND status='ACTIVE')`,id,f).Scan(&exists);err!=nil||!exists{httpapi.WriteProblem(w,404,"investment account not found");return};u,_:=auth.UserIDFromContext(r.Context());movement:=uuid.New();if _,err=h.db.Exec(r.Context(),`INSERT INTO investment_movements(id,investment_account_id,kind,amount_cents,effective_at,description,created_by) VALUES($1,$2,$3,$4,$5,$6,$7)`,movement,id,in.Kind,in.AmountCents,date,strings.TrimSpace(in.Description),u);err!=nil{httpapi.WriteProblem(w,500,"could not create movement");return};httpapi.WriteJSON(w,201,map[string]any{"id":movement,"amountCents":in.AmountCents,"kind":in.Kind})}
type vaultInput struct{AccountID uuid.UUID `json:"accountId"`;Name string `json:"name"`}
func(h *Handler) createVault(w http.ResponseWriter,r *http.Request){f,ok:=h.familyID(r);if !ok{httpapi.WriteProblem(w,404,"family not found");return};var in vaultInput;if json.NewDecoder(r.Body).Decode(&in)!=nil||in.AccountID==uuid.Nil||strings.TrimSpace(in.Name)==""{httpapi.WriteProblem(w,400,"account and name are required");return};var account bool;if err:=h.db.QueryRow(r.Context(),`SELECT EXISTS(SELECT 1 FROM accounts WHERE id=$1 AND family_id=$2 AND status='ACTIVE')`,in.AccountID,f).Scan(&account);err!=nil||!account{httpapi.WriteProblem(w,400,"account is not part of this family");return};id:=uuid.New();if _,err:=h.db.Exec(r.Context(),`INSERT INTO vaults(id,family_id,account_id,name) VALUES($1,$2,$3,$4)`,id,f,in.AccountID,strings.TrimSpace(in.Name));err!=nil{httpapi.WriteProblem(w,409,"could not create vault");return};httpapi.WriteJSON(w,201,map[string]any{"id":id,"accountId":in.AccountID,"name":strings.TrimSpace(in.Name),"balanceCents":int64(0)})}
func(h *Handler) listVaults(w http.ResponseWriter,r *http.Request){f,ok:=h.familyID(r);if !ok{httpapi.WriteProblem(w,404,"family not found");return};rows,err:=h.db.Query(r.Context(),`SELECT v.id,v.account_id,v.name,COALESCE(SUM(CASE WHEN m.kind='WITHDRAWAL' THEN -m.amount_cents ELSE m.amount_cents END),0) FROM vaults v LEFT JOIN vault_movements m ON m.vault_id=v.id WHERE v.family_id=$1 AND v.status='ACTIVE' GROUP BY v.id ORDER BY v.created_at`,f);if err!=nil{httpapi.WriteProblem(w,500,"could not load vaults");return};defer rows.Close();out:=make([]map[string]any,0);for rows.Next(){var id,account uuid.UUID;var name string;var balance int64;if err:=rows.Scan(&id,&account,&name,&balance);err!=nil{httpapi.WriteProblem(w,500,"could not load vaults");return};out=append(out,map[string]any{"id":id,"accountId":account,"name":name,"balanceCents":balance})};httpapi.WriteJSON(w,200,out)}
